from collections import deque

class MCMF:
    def __init__(self, n):
        self.n = n; self.g = [[] for _ in range(n)]; self.E = []
    def add(self, u, v, cap, cost):
        self.g[u].append(len(self.E)); self.E.append([v, cap, cost])
        self.g[v].append(len(self.E)); self.E.append([u, 0, -cost])
    def spfa(self, s, t):
        INF = float('inf')
        dist = [INF]*self.n; in_q = [False]*self.n
        prev = [-1]*self.n; dist[s] = 0; in_q[s] = True
        q = deque([s])
        while q:
            u = q.popleft(); in_q[u] = False
            for i in self.g[u]:
                v, c, w = self.E[i]
                if c and dist[u] + w < dist[v]:
                    dist[v] = dist[u]+w; prev[v] = i
                    if not in_q[v]: q.append(v); in_q[v] = True
        return dist, prev
    def flow(self, s, t):
        total_flow = 0; total_cost = 0
        while True:
            dist, prev = self.spfa(s, t)
            if dist[t] == float('inf'): break
            f = float('inf'); v = t
            while v != s:
                f = min(f, self.E[prev[v]][1]); v = self.E[prev[v]^1][0]
            v = t
            while v != s:
                self.E[prev[v]][1] -= f; self.E[prev[v]^1][1] += f
                v = self.E[prev[v]^1][0]
            total_flow += f; total_cost += f*dist[t]
        return total_flow, total_cost
